inline ModelT::ModelT(const ModelT &o)
      : magic(o.magic),
        version(o.version),
        initializer_blob(o.initializer_blob),
        unified(o.unified),
        rgba(o.rgba),
        unified_meta(o.unified_meta),
        unified_names(o.unified_names),
        rgba_meta(o.rgba_meta),
        rgba_names(o.rgba_names),
        unified_blob_offset(o.unified_blob_offset) {
  inputs.reserve(o.inputs.size());
  for (const auto &inputs_ : o.inputs) { inputs.emplace_back((inputs_) ? new vkop::model::ShapeRefT(*inputs_) : nullptr); }
  outputs.reserve(o.outputs.size());
  for (const auto &outputs_ : o.outputs) { outputs.emplace_back((outputs_) ? new vkop::model::ShapeRefT(*outputs_) : nullptr); }
  nodes.reserve(o.nodes.size());
  for (const auto &nodes_ : o.nodes) { nodes.emplace_back((nodes_) ? new vkop::model::NodeT(*nodes_) : nullptr); }
  initializers.reserve(o.initializers.size());
  for (const auto &initializers_ : o.initializers) { initializers.emplace_back((initializers_) ? new vkop::model::InitializerEntryT(*initializers_) : nullptr); }
  concurrent_levels.reserve(o.concurrent_levels.size());
  for (const auto &concurrent_levels_ : o.concurrent_levels) { concurrent_levels.emplace_back((concurrent_levels_) ? new vkop::model::ConcurrentLevelT(*concurrent_levels_) : nullptr); }
}

