inline bool SizePrefixedModelBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ModelIdentifier(), true);
}

template <bool B = false>
inline bool VerifyModelBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<vkop::model::Model>(ModelIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedModelBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<vkop::model::Model>(ModelIdentifier());
}

inline const char *ModelExtension() {
  return "vkopbin";
}

inline void FinishModelBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<vkop::model::Model> root) {
  fbb.Finish(root, ModelIdentifier());
}

inline void FinishSizePrefixedModelBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<vkop::model::Model> root) {
  fbb.FinishSizePrefixed(root, ModelIdentifier());
}

inline std::unique_ptr<vkop::model::ModelT> UnPackModel(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<vkop::model::ModelT>(GetModel(buf)->UnPack(res));
}

inline std::unique_ptr<vkop::model::ModelT> UnPackSizePrefixedModel(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<vkop::model::ModelT>(GetSizePrefixedModel(buf)->UnPack(res));
}

